package owl.nh;
import java.nio.file.*;import java.io.*;import java.net.*;import java.net.http.*;import java.time.Duration;import java.util.*;import java.util.concurrent.*;import javax.swing.*;import net.runelite.api.*;
/** Explicit opt-in; no installation identifier, IP collection, or persistent username. */
final class UsageReporting implements AutoCloseable {
 private final Path root;private final String session=UUID.randomUUID().toString();private final ScheduledExecutorService io=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"optional-usage-report");t.setDaemon(true);return t;});
 private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).followRedirects(HttpClient.Redirect.NEVER).build();
 private volatile boolean enabled,names,closed;private volatile String username="";private URI endpoint;private String key;
 UsageReporting(Path root){this.root=root;try{Properties p=read(root.resolve("usage-endpoint.properties"));URI candidate=URI.create(p.getProperty("endpoint",""));if(!"https".equalsIgnoreCase(candidate.getScheme())||candidate.getHost()==null||candidate.getUserInfo()!=null||candidate.getQuery()!=null||candidate.getFragment()!=null)return;endpoint=candidate.resolve("/heartbeat");key=p.getProperty("token","");if(key.length()<32){endpoint=null;return;}Properties consent=read(root.resolve("runtime/usage-consent.properties"));enabled=endpoint.toString().equals(consent.getProperty("endpoint"))&&Boolean.parseBoolean(consent.getProperty("enabled","false"));names=enabled&&Boolean.parseBoolean(consent.getProperty("username","false"));io.scheduleWithFixedDelay(()->send(false),5,30,TimeUnit.SECONDS);}catch(Exception ignored){endpoint=null;}}
 private static Properties read(Path p)throws IOException{Properties result=new Properties();if(Files.isRegularFile(p)&&Files.size(p)<8192)try(InputStream in=Files.newInputStream(p)){result.load(in);}return result;}
 void sample(Client client){Player player=client.getGameState()==GameState.LOGGED_IN?client.getLocalPlayer():null;username=enabled&&names&&player!=null&&player.getName()!=null?player.getName().replaceAll("<[^>]*>",""):"";}
 JMenu menu(java.awt.Component owner){JMenu menu=new JMenu("Usage privacy");JCheckBoxMenuItem count=new JCheckBoxMenuItem("Share anonymous active-session count",enabled),name=new JCheckBoxMenuItem("Also share my in-game username",names);count.setEnabled(endpoint!=null);name.setEnabled(endpoint!=null&&enabled);menu.add(count);menu.add(name);
  count.addActionListener(e->{if(count.isSelected()&&JOptionPane.showConfirmDialog(owner,"Send an anonymous session heartbeat every 30 seconds to "+endpoint.getHost()+"?\nReports pass through Cloudflare to the app administrator. Connection providers can see IPs; Turbo does not store them.\nThe administrator can see recent session counts. No username is sent unless separately enabled.\nYou can withdraw here at any time.","Optional usage reporting",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION){count.setSelected(false);return;}boolean was=enabled;enabled=count.isSelected();if(!enabled){names=false;name.setSelected(false);username="";if(was)io.execute(()->send(true));}name.setEnabled(enabled);save();if(enabled)io.execute(()->send(false));});
  name.addActionListener(e->{if(name.isSelected()&&JOptionPane.showConfirmDialog(owner,"Also send your current in-game username to the administrator?\nIt is held only in memory and expires within two minutes without reports.\nYour username will be visible on the admin dashboard.","Optional username sharing",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)name.setSelected(false);names=name.isSelected();if(!names)username="";save();io.execute(()->send(false));});if(endpoint==null){JMenuItem missing=new JMenuItem("Reporting is not configured");missing.setEnabled(false);menu.add(missing);}return menu;
 }
 private void save(){try{Path path=root.resolve("runtime/usage-consent.properties");Files.createDirectories(path.getParent());Properties p=new Properties();p.setProperty("endpoint",endpoint.toString());p.setProperty("enabled",Boolean.toString(enabled));p.setProperty("username",Boolean.toString(names));try(OutputStream out=Files.newOutputStream(path)){p.store(out,"Optional reporting preferences; no usernames or credentials");}}catch(IOException ignored){}}
 private void send(boolean leave){if(endpoint==null||!leave&&(!enabled||closed))return;try{com.google.gson.JsonObject data=new com.google.gson.JsonObject();data.addProperty("session",session);if(leave)data.addProperty("leave",true);else if(names)data.addProperty("username",username);HttpRequest request=HttpRequest.newBuilder(endpoint).timeout(Duration.ofSeconds(6)).header("Content-Type","application/json").header("X-Turbo-Key",key).POST(HttpRequest.BodyPublishers.ofString(data.toString())).build();http.send(request,HttpResponse.BodyHandlers.discarding());}catch(Exception ignored){/* Reporting failures never affect gameplay and contain no user-content logs. */}}
 public void close(){if(closed)return;closed=true;username="";if(enabled)io.execute(()->send(true));io.shutdown();}
}
